CREATE TABLE IF NOT EXISTS email_ingestions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), ticket_id UUID REFERENCES tickets(id), source_mailbox TEXT NOT NULL, sender TEXT NOT NULL, subject TEXT NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'received', raw_payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), project_id UUID REFERENCES projects(id), ticket_id UUID REFERENCES tickets(id), title TEXT NOT NULL, document_type TEXT NOT NULL DEFAULT 'general', storage_url TEXT NOT NULL, checksum TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_by_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mobile_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), asset_id UUID REFERENCES monitoring_assets(id), user_id UUID REFERENCES users(id), platform TEXT NOT NULL, device_name TEXT NOT NULL, os_version TEXT, app_version TEXT, push_token TEXT, management_status TEXT NOT NULL DEFAULT 'enrolled', last_seen_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS remote_control_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), asset_id UUID REFERENCES monitoring_assets(id), requested_by_user_id UUID REFERENCES users(id), status TEXT NOT NULL DEFAULT 'requested', provider TEXT NOT NULL DEFAULT 'manual', session_url TEXT, started_at TIMESTAMPTZ, ended_at TIMESTAMPTZ, audit_log JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patch_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), asset_id UUID REFERENCES monitoring_assets(id), title TEXT NOT NULL, patch_identifier TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'medium', status TEXT NOT NULL DEFAULT 'pending', scheduled_at TIMESTAMPTZ, installed_at TIMESTAMPTZ, result_message TEXT, created_by_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS siem_correlations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), asset_id UUID REFERENCES monitoring_assets(id), alert_id UUID REFERENCES monitoring_alerts(id), correlation_key TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', summary TEXT NOT NULL, event_count INT NOT NULL DEFAULT 1, first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), raw_events JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
